insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 3, 'Mas é Baruque filho de Nerias que te incita contra nós, para nos entregar nas mãos dos caldeus, para nos matar ou nos fazer transportar cativos à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 4, 'Assim Joanã filho de Careá, e todos os comandantes dos exércitos, e todo o povo, não obedeceram à voz do SENHOR para ficarem na terra de Judá;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 5, 'Em vez disse, Joanã filho de Careá, e todos os comandantes dos exércitos, tomaram a todo o restante de Judá, que tinham voltado de todas as nações para onde haviam sido lançados, para morarem na terra de Judá:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 6, 'Homens, mulheres, crianças, as filhas do rei, e a toda alma que Nabuzaradã capitão da guarda tinha deixado com Gedalias filho de Aicã filho de Safã, e [também] ao profeta Jeremias, e a Baruque filho de Nerias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 7, 'E vieram à terra do Egito, porque não obedeceram à voz do SENHOR; e chegaram até Tafnes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 8, 'Então veio a palavra do SENHOR a Jeremias em Tafnes, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 9, 'Toma em tua mão pedras grandes, e as esconde entre o barro no forno que está à porta da casa de Faraó em Tafnes, diante dos olhos de homens judeus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 10, 'E dize-lhes: Assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu enviarei, e tomarei a Nabucodonosor rei da Babilônia, meu servo, e porei seu trono sobre estas pedras que escondi; e ele estenderá sua tenda real sobre elas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 11, 'E ele virá, e ferirá a terra do Egito: os que [estão condenados] para a morte, à morte; os que para o cativeiro, ao cativeiro, e os que para a espada, à espada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 12, 'E acenderei fogo às casas dos deuses do Egito; e ele as queimará, e os levará cativos; e ele se vestirá da terra do Egito, tal como o pastor se veste de sua capa; e ele sairá de lá em paz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 43, 13, 'E quebrará as estátuas de Bete-Semes, que fica na terra do Egito, e queimará a fogo as casas dos deuses do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 1, 'Palavra que veio a Jeremias quanto a todos os judeus habitantes na terra do Egito, que moravam em Migdol, Tafnes, Nofe, e na terra de Patros, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 2, 'Assim diz o SENHOR dos exércitos, Deus de Israel: Vós vistes todo o mal que eu trouxe sobre Jerusalém e sobre todas as cidades de Judá; e eis que hoje elas estão desoladas, e ninguém nelas habita;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 3, 'Por causa da maldade deles, que fizeram para me irritar, indo oferecer incenso, [e] servindo a outros deuses que nunca conheceram, nem eles, nem vós, nem vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 4, 'E enviei até vós todos os meus servos, os profetas, persistindo em enviá-los, dizendo: Não façais, pois, esta coisa abominável, e eu odeio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 5, 'Porém não obedeceram, nem inclinaram seus ouvidos para se converterem de sua maldade, para não oferecer incenso a outros deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 6, 'Por isso se derramou minha indignação e minha ira, e acendeu-se nas cidades de Judá e nas ruas de Jerusalém, e tornaram-se em desolação e em destruição tal como está hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 7, 'Agora pois, assim diz o SENHOR dos exércitos, Deus de Israel: Por que fazeis tão grande mal contra vossas almas, para serdes eliminados homem e mulher, criança e bebê de peito, do meio de Judá, sem que vos sobre um restante sequer;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 8, 'Irritando-me com as obras de vossas mãos, oferecendo incenso a outros deuses na terra do Egito, para onde entrastes para morar; de modo que sereis eliminados, e servireis de maldição e de humilhação entre todas as nações da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 9, 'Por acaso já vos esquecestes das maldades de vossos pais, das maldades dos reis de Judá, das maldades de suas mulheres, e das vossas [próprias] maldades, e das maldades de vossas mulheres, que foram feitas na terra de Judá e nas ruas de Jerusalém?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 10, 'Até hoje não se contristaram, nem temeram, nem andaram em minha lei, nem em meus estatutos que pus diante de vós e diante de vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 11, 'Portanto assim diz o SENHOR dos exércitos, Deus de Israel: Eis que eu dirijo meu rosto a vós para o mal, e para destruir a todo Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 12, 'E tomarei os restantes de Judá que dirigiram seus rostos para entrarem na terra do Egito para ali morar, e na terra do Egito serão todos consumidos; cairão a espada, e serão consumidos pela fome; desde o menor até o maior, pela espada e pela fome morrerão. E servirão de maldição e de espanto; de amaldiçoamento e de humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 13, 'Pois castigarei aos que moram na terra do Egito, tal como castiguei a Jerusalém, com espada, fome e pestilência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 14, 'De maneira que, dos restantes de Judá que entraram na terra do Egito para morar ali, não haverá quem escape, nem quem reste vivo, para voltar à terra de Judá, da qual eles anseiam para voltar a habitar lá; pois não voltarão, a não ser alguns fugitivos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 15, 'Então todos os homens que sabiam que suas mulheres haviam oferecido incenso a outros deuses, e todas as mulheres que estavam presentes, uma grande multidão, e todo o povo que habitava na terra do Egito, em Patros, responderam a Jeremias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 16, 'Quanto a palavra que tu nos falaste em nome do SENHOR, não daremos ouvidos a ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 17, 'Em vez disso certamente faremos toda a palavra que saiu de nossa boca, para oferecer incenso à rainha dos céus, e para lhe apresentar ofertas de bebidas, tal como temos feito, nós e nossos pais, nossos reis e nossos príncipes, nas cidades de Judá, e nas ruas de Jerusalém, quando nos fartávamos de pão, vivíamos bem, e não víamos calamidade alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 18, 'Mas desde que cessamos de oferecer incenso à rainha do céus, e de derramar ofertas de bebidas, tivemos falta de tudo, e fomos consumidos pela espada e pela fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 19, 'E quando oferecemos incenso à rainha do céus, e lhe derramamos ofertas de bebidas, por acaso nós lhe fizemos bolos para lhe prestar culto, e lhe derramamos ofertas de bebidas, sem nossos maridos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 20, 'Então Jeremias disse a todo o povo, aos homens e às mulheres, e a todo o povo que lhe tinha respondido isto, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 21, 'Por acaso não se lembrou o SENHOR, e não veio a sua mente o incenso que oferecestes nas cidades de Judá, e nas praças de Jerusalém, vós e vossos pais, vossos reis e vossos príncipes, e o povo da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 22, 'De tal maneira que o SENHOR não podia mais aguentar, por causa da maldade de vossas ações, por causa das abominações que fizestes; por isso vossa terra se tornou em desolação, em espanto, e em maldição, até não restar morador, tal como hoje está.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 23, 'Pois oferecestes incenso e pecastes contra o SENHOR, e não obedecestes à voz do SENHOR, nem andastes em seu lei, seus estatutos, e seus testemunhos; por isso veio sobre vós este mal, tal como há hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 24, 'Disse mais Jeremias a todo o povo, e a todas as mulheres: Ouvi a palavra do SENHOR, todos vós de Judá, que estais na terra do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 25, 'Assim diz o SENHOR dos exércitos, Deus de Israel, dizendo: Vós e vossas mulheres não somente falastes por vossas bocas, mas também com vossas mãos o cumpristes, dizendo: Certamente faremos nossos votos que fizemos, de oferecer incensos à rainha dos céus, e lhe apresentar ofertas de bebidas; Com certeza confirmastes vossos votos, e com certeza cumpristes vossos votos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 26, 'Portanto ouvi a palavra do SENHOR, todos vós de Judá que habitais na terra do Egito: Eis que juro por meu grande nome, diz o SENHOR, que nunca mais meu nome será chamado pela boca homem algum de Judá, em toda a terra do Egito, dizendo: Vive o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 27, 'Eis que eu os observarei para o mal, e não para o bem; e todos os homens de Judá que estão na terra do Egito serão consumidos pela espada e pela fome, até que se acabem por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 28, 'E os que escaparem do espada voltarão da terra do Egito para a terra de Judá, poucos em número; e todo o restante de Judá, que entrou em Egito para ali morar, saberá qual palavra se confirmará, se a minha ou a sua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 29, 'E isto tereis por sinal, diz o SENHOR, de que neste lugar eu vos castigo, para que saibais que certamente minhas palavras se confirmarão contra vós para o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 44, 30, 'Assim diz o SENHOR: Eis que eu entregarei ao Faraó Ofra, rei do Egito, nas mãos de seus inimigos, e nas mão dos que buscam sua morte, assim como entreguei a Zedequias rei de Judá nas mãos de Nabucodonosor rei de Babilônia, seu inimigo, e que buscava sua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 45, 1, 'Palavra que o profeta Jeremias falou a Baruque filho de Nerias, quando ele escrevia num livro aquelas palavras da boca de Jeremias, no quinto ano de Jeoaquim filho de Josias, rei de Judá, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 45, 2, 'Assim diz o SENHOR Deus de Israel, quanto a ti, Baruque:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 45, 3, 'Tu disseste: Ai de mim agora! Pois o SENHOR me acrescentou tristeza sobre minha dor; já estou cansado de meu gemido, e não acho descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 45, 4, 'Assim lhe dirás: Assim diz o SENHOR: Eis que o que edifiquei eu destruo; e o que plantei eu arranco, até toda esta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 45, 5, 'E tu buscarias para ti grandezas? Não [as] busques; porque eis que eu trago o mal sobre toda carne, diz o SENHOR, mas conservarei tua vida em todos os lugares para onde fores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 1, 'Palavra do SENHOR que veio ao profeta Jeremias, contra as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 2, 'Quanto ao Egito: contra o exército de Faraó Neco, rei do Egito, que estava junto ao rio Eufrates em Carquemis, ao qual Nabucodonosor rei da Babilônia feriu no quarto ano de Jeoaquim filho de Josias, rei de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 3, 'Preparai os escudos maior e o menor, e vinde à guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 4, 'Selai os cavalos, e subi, vós os cavaleiros, e apresentai-vos com capacetes; limpai as lanças, vesti-vos de couraças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 5, 'Por que razão vejo os medrosos tornando atrás? E seus guerreiros são abatidos, e vão fugindo, sem olharem para trás; o terror está por todos os lados,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 6, 'Não fuja o ligeiro, nem escape o guerreiro; para o norte, junto à margem do rio do Eufrates, tropeçaram e caíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 7, 'Quem é este que sobe como o Nilo, cujas águas se movem como rios?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 8, 'O Egito vem subindo como o Nilo, e [suas] águas se agitam como rios, e disse: Subirei, [e] cobrirei a terra; destruirei a cidade, e os que nela habitam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 9, 'Subi, cavalos, e rangei, carruagens; e saiam os guerreiros; os de Cuxe e os de Pute que tomam escudo, e os de Lude que tomam e encurvam o arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 10, 'Porém esse dia pertence ao Senhor DEUS dos exércitos, o dia de vingança, para ele se vingar de seus adversários; e a espada devorará, se fartará, e se embriagará do sangue deles; pois o Senhor DEUS dos exércitos tem [para si] um sacrifício na terra do norte, junto ao rio Eufrates.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 11, 'Sobe a Gileade, e toma bálsamo, ó virgem filha do Egito; em vão multiplicas os remédios, [pois] não há cura para ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 12, 'As nações ouviram da tua vergonha, e teu clamor encheu a terra: pois um guerreiro tropeçou contra [outro] guerreiro, e ambos juntamente caíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 13, 'Palavra que o SENHOR falou ao profeta Jeremias quanto à vinda de Nabucodonosor, rei da Babilônia, para ferir a terra do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 14, 'Anunciai no Egito, e declarai em Migdol; declarai também em Nofe e em Tafnes; dizei: Firma uma posição, e prepara-te; pois a espada está para devorar o que há ao redor de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 15, 'Por que teus guerreiros foram derrubados? Não puderam ficar de pé, pois o SENHOR os empurrou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 16, 'Ele multiplicou os que tropeçaram; caíram cada um sobre o outro, e disseram: Levanta-te e voltemo-nos a nosso povo, e à terra de nosso nascimento, por causa da espada opressora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 17, 'Ali gritarão: O Faraó rei do Egito, é [apenas] um barulho; ele deixou passar o tempo determinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 18, 'Vivo eu, diz o Rei, cujo nome é EU-SOU dos exércitos, que como o Tabor entre os montes, e como o Carmelo no mar, assim ele virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 19, 'Faz para ti a bagagem para a ida ao cativeiro, ó moradora, filha do Egito; porque Nofe se tornará em desolação, e será devastada até não haver ali morador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 20, 'O Egito é uma bezerra formosa; mas a mosca carniceira vem do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 21, 'Até seus soldados mercenários em meio dela são como bezerros cevados; porém também eles se virarão para trás, e juntamente fugirão; eles não permanecerão em postos, porque o dia de sua ruína, o tempo de sua punição, veio sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 22, 'Seu ruído sairá como de serpente; pois [seus inimigos] virão com poder; a ela virão com machados, como se fossem cortadores de lenha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 23, 'Cortarão o seu bosque,diz o SENHOR, ainda que não possam ser contados; porque são mais que gafanhotos, não se pode enumerá- los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 24, 'A filha do Egito será envergonhada; entregue será nas mãos do povo do norte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 25, 'Diz o SENHOR dos exércitos, Deus de Israel: Eis que eu punirei a Amom de Nô, a Faraó e ao Egito; a seus deuses e a seus reis; tanto a Faraó como aos que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 26, 'E os entregarei nas mãos dos que buscam [tirar] sua vida, e nas mãos de Nabucodonosor rei de Babilônia, e nas mãos de seus servos; porém depois será habitada como nos dias anteriores,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 27, 'Mas tu não temas, meu servo Jacó, nem te espantes, ó Israel; porque eis que te salvarei desde [as terras] de longe, e teus descendentes da terra de seu cativeiro. E Jacó voltará, descansará, e viverá em paz; e não haverá quem o atemorize.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 46, 28, 'Tu, meu servo Jacó, não temas,diz o SENHOR; pois eu estou contigo; porque destruirei por completo todas as nações entre as quais eu te lancei; porem a ti não destruirei por completo, mas te castigarei com moderação, e não te deixarei impune.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 1, 'Palavra do SENHOR que veio ao profeta Jeremias sobre os filisteus, antes que Faraó ferisse a Gaza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 2, 'Assim diz o SENHOR: Eis que águas sobem do norte, e se tornarão em correnteza transbordante, e inundarão a terra e sua plenitude, as cidades, e moradores delas; os homens gritarão, e todos os moradores da terra uivarão,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 3, 'Ao ruído dos cascos de seus fortes [cavalos] ,o tremor de suas caruagens, e o estrondo de suas rodas; os pais não olharão para os filhos por causa da fraqueza das mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 4, 'Por causa do dia que vem, para arruinar a todos os filisteus, para cortar a Tiro e a Sidom todo ajudador que restar; pois o SENHOR destruirá aos filisteus, ao resto da ilha de Caftor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 5, 'Veio calvície sobre Gaza; Ascalom e o resto de seu vale foram cortados fora. Até quando te ferirás com arranhões?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 6, 'Ah, espada do SENHOR! Até quando não te aquietarás? Volta-te em tua bainha, descansa, e aquieta-te.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 47, 7, 'Como te aquietarias? Pois o SENHOR lhe deu mandado contra Ascalom, e contra o litoral, [e] ali ele a ordenou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 1, 'Sobre Moabe.Assim diz o SENHOR dos exércitos, Deus de Israel: Ai de Nebo! Pois foi arruinada; envergonhada está Quiriataim, já foi tomada; Misgabe está envergonhada e espantada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 2, 'Já não há mais exaltação em Moabe; em Hesbom tramaram o mal contra ela, [dizendo] : Vinde, e a eliminemos das nações. Também tu, Madmém, serás cortada fora; a espada irá atrás de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 3, '[Ouve-se] uma voz de clamor de Horonaim: Ruína e grande destruição!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 4, 'Moabe foi destruída; fizeram com que se ouvisse o grito de seus pequenos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 5, 'Pois na subida de Luíte subirão com grande choro; pois na descida de Horonaim os inimigos [de Moabe] ouviram clamor de destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 6, 'Fugi, livrai vossa vida, e sereis como um arbusto no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 7, 'Pois por causa de tua confiança confiaste em tuas obras e em teus tesouros, tu também serás tomada; e Quemos irá ao cativeiro, seus sacerdotes e juntamente seus príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 8, 'Pois virá o destruidor a cada uma das cidades, e nenhuma cidade escapará; e perecerá também o vale, e será destruída a planície,pois assim diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 9, 'Dai asas a Moabe, para que ele saia voando; pois suas cidades se tornarão desertas até não restar quem more nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 10, 'Maldito aquele que fizer enganosamente a obra do SENHOR, e maldito aquele que detiver sua espada do sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 11, 'Tranquilo esteve Moabe desde sua juventude, e sobre suas impurezas esteve quieto; e não foi esvaziado de vaso em vaso, nem nunca foi ao cativeiro; por isso seu sabor ficou nele, e seu cheiro não mudou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 12, 'Por isso eis que vêm dias, diz o SENHOR, em que eu lhe enviarei derramadores que o derramarão; e esvaziarão seus vasos, e romperão seus jarros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 13, 'E Moabe se envergonhará de Quemos, assim como a casa de Israel se envergonhou de Betel, [que era] sua confiança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 14, 'Como direis: Somos guerreiros, homens valentes para a guerra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 15, 'Moabe é destruído, e suas cidades invadidas, e seus melhores rapazes descem ao degoladouro, diz o rei, cujo nome é EU-SOU dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 16, 'Próxima está a vinda da perdição de Moabe; e seu desastre vem com muita pressa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 17, 'Condoei-vos dele todos vós que estais ao seu redor, e todos vós que sabeis seu nome. Dizei: Como se quebrou a vara forte, o belo cajado!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 18, 'Desce da [tua] glória, e senta-te no lugar seco, ó moradora, filha de Dibom; pois o destruidor de Moabe subiu contra ti, e arruinou tuas fortalezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 19, 'Para-te no caminho, e olha, ó moradora de Aroer; pergunta ao que vai fugindo, e à que escapou, dize: O que aconteceu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 20, '[Responderão] : Moabe está envergonhado, porque foi quebrantado; uivai e gritai; anunciai em Arnom que Moabe foi destruído,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 21, 'O julgamento também veio juízo sobre a terra da planície: sobre Holom, sobre Jazá, e sobre Mefate;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 22, 'Sobre Dibom, sobre Nebo, e sobre Bete-Diblataim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 23, 'Sobre Quiriataim, sobre Bete-Gamul, e sobre Bete-Meom;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 24, 'Sobre Queriote, sobre Bosra, e sobre todas as cidades da terra de Moabe, as de longe e as de perto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 25, 'O poder de Moabe foi cortado, e seu braço quebrado,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 26, 'Embriagai-o, pois contra o SENHOR se engrandeceu; e Moabe se revolverá sobre seu vômito, e ele também será por escárnio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 27, 'Pois para ti não foi Israel por escárnio? Por acaso ele foi achado entre ladrões, para que balances a cabeça quando falas dele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 28, 'Deixai as cidades, e habitai em rochedos, ó moradores de Moabe; e sejais como a pomba que faz ninho nas brechas da boca da caverna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 29, 'Temos ouvido a soberba de Moabe, que é soberbo demais, assim como sua arrogância e seu orgulho, sua altivez e a altura de seu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 30, 'Eu conheço sua insolência,diz o SENHOR; porém não será assim; suas mentiras lhe serão em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 31, 'Por isso eu uivarei por Moabe, e gritarei por todo Moabe; gemerão por causa dos homens de Quir-Heres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 32, 'Com o choro de Jazer chorarei por ti, ó vide de Sibma; teus sarmentos passaram o mar, [e] chegaram até o mar de Jazer; [porém] o destruidor veio sobre os frutos de teu verão, e sobre tua vindima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 33, 'Assim foram tirados a alegria e o regozijo dos campos férteis, e da terra de Moabe: pois fiz cessar o vinho das prensas; já não pisarão [uvas] com júbilo; o grito não será de júbilo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 34, 'Houve um grito desde Hesbom até Eleale e até Jaaz; deram sua voz desde Zoar até Horonaim e Eglate-Selísia; pois também as águas de Ninrim serão assoladas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 35, 'E eu,diz o SENHOR, farei cessar de Moabe quem sacrifique no lugar alto, e quem ofereça incenso a seus deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 36, 'Portanto meu coração ressoará como flautas por causa de Moab; também meu coração ressoará como flautas pelos homens de Quir-Heres; pois as riquezas que tinham acumulado se perderam;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 37, 'Pois em toda cabeça haverá calva, e toda barba será cortada; sobre todas mãos há arranhões, e sobre todos os lombos há sacos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 38, 'Sobre todas os terraços de Moabe e em suas ruas, em todo ele haverá pranto; pois eu quebrantei a Moabe como a um vaso desagradável,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 39, 'Como foi quebrantado! Como uivam! Como Moabe virou as costas, e se envergonhou! Assim Moabe servirá de escárnio e de espanto a todos os que estão ao seu redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 40, 'Pois assim diz o SENHOR: Eis que voará como águia, e estenderá suas asas sobre Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 41, 'Tomadas são as cidades, e invadidas são as fortalezas; e o coração dos guerreiros de Moabe naquele dia será como o coração de mulher em dores de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 42, 'E Moabe será destruído de modo que deixará de ser povo, pois se engrandeceu contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 43, 'Medo, cova, e laço [vem] sobre ti, ó morador de Moabe,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 44, 'O que fugir do medo, cairá na cova; e o que subir da cova, ficará preso do laço; porque eu trarei sobre ele, sobre Moabe, o ano de sua punição,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 45, 'Os que fugiam da força, paravam à sombra de Hesbom; porém fogo saiu de Hesbom, e labareda do meio de Seom, e queimou a testa de Moabe, e o topo da cabeça dos filhos do tumulto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 46, 'Ai de ti, Moabe! Pereceu o povo de Quemos; pois teus filhos foram levados cativos, e tuas filhas foram em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 48, 47, 'Porém restaurarei Moabe de seu infortúnio nos últimos dias, diz o SENHOR. Até aqui é o julgamento de Moabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 1, 'Sobre os filhos de Amom.Assim diz o SENHOR: Por acaso Israel não tem filhos, nem tem herdeiro? Por que, pois, Malcã tomou posse de Gade, e seu povo habitou em suas cidades?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 2, 'Portanto eis que vêm dias,diz o SENHOR, em que farei ouvir em Rabá dos filhos de Amom clamor de guerra; e se tornará em um amontoado de ruínas, e suas vilas serão queimadas a fogo; e Israel tomará posse daqueles que tinham lhes tomado, disse o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 3, 'Uiva, ó Hesbom, porque Ai é destruída; clamai, ó filhas de Rabá, vesti-vos de sacos, lamentai, e rodeai pelas cercas, porque Malcã irá em cativeiro, seus sacerdotes e juntamente seus príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 4, 'Por que te orgulhas dos vales? Teu vale se desfez, ó filha rebelde, que confia em seus tesouros, [dizendo] : Quem virá contra mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 5, 'Eis que trago medo sobre ti,diz o Senhor o SENHOR dos exércitos, de todos os que estão ao redor de ti; e sereis forçados a fugir, cada um por si, e não haverá quem consiga reunir os que andam sem rumo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 6, 'Mas depois disso restaurarei os filhos de Amom de seu infortúnio, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 7, 'Sobre Edom.Assim diz o SENHOR dos exércitos: Por acaso não há mais sabedoria em Temã? Pereceu o conselho dos prudentes? Estragou-se sua sabedoria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 8, 'Fugi, voltai-vos, escondei-vos em profundezas para habitar, ó moradores de Dedã; porque trarei sobre ele a calamidade de Esaú no tempo [em que] eu o punir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 9, 'Se recolhedores de uva viessem contra ti, por acaso não deixarão sobras? Se ladrões de noite [viessem] não te danificariam [apenas] o que achassem suficiente?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 10, 'Mas eu despirei a Esaú, descobrirei seus esconderijos, e não poderá se esconder; será destruída sua descendência, e também seus irmãos e seus vizinhos; e deixará de existir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 11, 'Deixa teus órfãos, eu os criarei; e em mim confiarão tuas viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 12, 'Pois assim diz o SENHOR: Eis que os que não estavam condenados a beberem do cálice, certamente o beberão; e ficarias tu impune por completo? Não ficarás impune, e certamente beberás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 13, 'Pois jurei por mim mesmo,diz o SENHOR, que Bozra se tornará em espanto, humilhação, deserto e maldição; e todas as suas cidades se tornarão desolações perpétuas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 14, 'Ouvi uma notícia do SENHOR que um mensageiro foi às nações, [para dizer] : Juntai-vos, e vinde contra ela, e levantai-vos para a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 15, 'Porque eis te fiz pequeno entre as nações, desprezado entre os homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 16, 'O terror que tu causas te enganou, assim como a arrogância de teu coração; tu que habitas nas cavernas das rochas, que tens a altura dos montes; ainda que levantes teu ninho como a águia, de lá eu te derrubarei,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 17, 'Assim Edom servirá de espanto; todo aquele que passar por ela se espantará, e assoviará por causa de todas as suas pragas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 18, 'Tal como a destruição de Sodoma e de Gomorra, e de suas cidades vizinhas,diz o SENHOR, ninguém habitará ali, nem filho de homem morará nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 19, 'Eis que será como o leão que sobe da mata do Jordão contra a morada do forte; porque repentinamente o farei correr dela, e ordenarei contra ela a quem eu escolher; pois quem é semelhante a mim? E quem manda em mim? E quem é o pastor que pode subsistir diante de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 20, 'Portanto ouvi o conselho do SENHOR, que ele determinou sobre Edom; e seus pensamentos, que decidiu sobre os moradores de Temã: Certamente os menores do rebanho os arrastarão, e destruirão suas moradas com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 21, 'A terra treme do estrondo da queda deles; e o grito de sua voz foi ouvida até no mar Vermelho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 22, 'Eis que como águia subirá e voará, e estenderá suas asas sobre Bozra; e o coração dos guerreiros de Edom será naquele dia como o coração de mulher em dores de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 23, 'Sobre Damasco. Envergonharam-se Hamate e Arpade, porque ouviram más notícias; derreteram-se em mar de angústia, não podem se sossegar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 24, 'Enfraquecida está Damasco; virou-se para fugir, e foi tomada de medo; angústia e dores a tomaram, como de mulher que está de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 25, 'Como não foi abandonada a famosa cidade, a cidade de minha alegria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 26, 'Por isso seus rapazes cairão em suas ruas, e todos os homens de guerra serão mortos naquele dia,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 27, 'E acenderei fogo no muro de Damasco, que consumirá as casas de Ben-Hadade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 28, 'Sobre Quedar e dos reinos de Hazor, os quais Nabucodonosor, rei da Babilônia, feriu.Assim diz o SENHOR: Levantai-vos, subi contra Quedar, e destruí os filhos de oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 29, 'Tomarão suas tendas e seu gados; suas cortinas, e todos os seus vasos; e seus camelos, levarão para si; e lhes gritarão: O medo está ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 30, 'Fugi, afastai-vos para muito longe, buscai profundezas para habitar, ó moradores de Hazor, diz o SENHOR; porque Nabucodonosor, rei da Babilônia, tomou conselho contra vós, e pensou um plano contra vós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 31, 'Levantai-vos, subi contra uma nação tranquila, que habita em segurança,diz o SENHOR, que nem têm portas nem ferrolhos, que vivem sozinhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 32, 'E seus serão camelos para presa, e a multidão de seus gados para despojo; e os espalharei por todos os lados, até os cantos mais distantes; e por todos os lados lhes trarei sua ruína,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 33, 'E Hazor se tornará uma morada de chacais, desolada para sempre; ninguém habitará ali, nem filho de homem morará nela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 34, 'Palavra do SENHOR que veio ao profeta Jeremias, sobre Elão, no princípio do reinado de Zedequias rei de Judá, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 35, 'Assim diz o SENHOR dos exércitos: Eis que quebrarei o arco de Elão, o principal de seu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 36, 'E trarei sobre Elão os quatro ventos dos quatro cantos do céu, e os espalharei por todos estes ventos; não haverá nação para onde não venham exilados de Elão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 37, 'E farei com que Elão tenha medo diante de seus inimigos, e diante dos que buscam [tirar] sua vida; e trarei o mal sobre eles, o furor de minha ira,diz o SENHOR; e mandarei a espada atrás deles, até que os acabe por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 38, 'E porei meu trono em Elão, e destruirei dali o rei e os príncipes,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 49, 39, 'Mas será nos últimos dias, que restaurarei Elão de seu infortúnio, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 1, 'Palavra que o SENHOR falou sobre a Babilônia, sobre a terra dos caldeus, por meio do profeta Jeremias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 2, 'Anunciai entre as nações, declarai, e levantai bandeira; declarai, e não encubrais: dizei: Tomada é Babilônia, Bel é envergonhado, Merodaque é despedaçado; envergonhados são seus ídolos, despedaçados estão suas imagens de idolatria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 3, 'Pois subiu contra ela uma nação do norte, a qual tornará sua terra em desolação, e não haverá morador nela; desde os homens até os animais fugiram e se afastaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 4, 'Naqueles dias e naquele tempo,diz o SENHOR, os filhos de Israel virão, eles e juntamente os filhos de Judá; virão andando e chorando, e buscarão ao SENHOR seu Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 5, 'Perguntarão por Sião, pelo caminho para onde voltarão seus rostos, [dizendo] : Vinde, e juntai-vos ao SENHOR [com] um pacto eterno, que jamais será esquecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 6, 'Meu povo tem sido ovelhas perdidas; seus pastores as fizeram errar, pelos montes as desviaram; andaram de monte em morro, esqueceram-se de seu lugar de descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 7, 'Todos quantos as achavam, as comiam; e adversários diziam: Nenhuma culpa teremos, pois pecaram contra o SENHOR, a morada da justiça [contra] o SENHOR, a esperança de seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 8, 'Fugi do meio da Babilônia, e saí da terra dos caldeus; e sede como os bodes adiante do rebanho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 9, 'Porque eis que eu levantarei e farei subir contra a Babilônia um ajuntamento de grandes povos da terra do norte; e se prepararão contra ela, e dali será tomada; suas flechas serão como de um habilidoso guerreiro, que não voltarão em vão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 10, 'E a Caldeia será objeto de saque; todos os que a saquearem serão fartos,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 11, 'Visto que vós vos alegrastes, que vos enchestes de prazer, vós saqueadores de minha propriedade; visto que vos inchastes como bezerra gorda, e relinchastes como cavalos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 12, '[Por isso] vossa mãe será muito envergonhada, será humilhada a que vos gerou; eis que ela será a última das nações: deserto, secura, e desolação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 13, 'Por causa da ira do SENHOR não será habitada; ela, porém será totalmente desolada; qualquer um passar pela Babilônia se espantará e assoviará por causa de todas as suas pragas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 14, 'Preparai-vos em linha de batalha contra Babilônia ao redor, todos vós que armais arcos; atirai contra ela, não poupeis as flechas; pois ela pecou contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 15, 'Gritai contra ela ao redor, [pois] já se rendeu; caíram seus fundamentos, derrubados são seus muros, pois esta é vingança do SENHOR. Vingai-vos dela; fazei com ela assim como ela fez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 16, 'Exterminai da Babilônia o semeador, e o que usa a foice no tempo da ceifa; por causa da espada opressora, cada um se voltará ao seu povo, cada um fugirá para sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 17, 'Israel é um cordeiro desgarrado, que leões afugentaram; o rei da Assíria foi o primeiro que o devorou; e este, Nabucodonosor rei da Babilônia, o último, que lhe quebrou os ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 18, 'Portanto assim diz o SENHOR dos exércitos, Deus de Israel: Eis que punirei ao rei de Babilônia e a sua terra assim como puni ao rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 19, 'E voltarei a trazer Israel à sua morada, no Carmelo e em Basã se alimentará; nos montes de Efraim e de Gileade sua alma farta será.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 20, 'Naqueles dias e naquele tempo,diz o SENHOR, a maldade de Israel será buscada, mas não [será encontrada] ; e [buscados] os pecados de Judá, mas não se acharão; porque perdoarei aos restantes que eu deixar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 21, 'Sobe contra ela, a terra de Merataim, e contra os moradores de Pecode; assola e destrói por completo atrás deles,diz o SENHOR, e faze conforme a tudo o que te mandei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 22, 'Há barulho de guerra na terra, e de grande destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 23, 'Como foi cortado e quebrado o martelo de toda a terra! Como Babilônia se tornou em espanto entre as nações!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 24, 'Pus armadilha para ti, e também foste capturada, ó Babilônia, antes de tu perceberes; foste achada, e também presa, porque lutaste contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 25, 'O SENHOR abriu o teu arsenal, e tirou os instrumentos de sua ira; porque esta é a obra do Senhor DEUS dos exércitos, na terra dos caldeus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 26, 'Vinde contra ela desde o lugar mais distante; abri seus celeiros; tornai-a em amontoados, e destruí-a por completo; que nada reste dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 27, 'Matai à espada todos os seus novilhos; que ela desça ao matadouro. Ai deles! Porque veio o seu dia, o tempo de sua punição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 28, 'Eis a voz dos que fugiram e escaparam da terra de Babilônia, para anunciar em Sião a vingança do SENHOR nosso Deus, a vingança de seu templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 29, 'Convocai contra a Babilônia os flecheiros, todos os que armam arcos; assentai o acampamento ao redor dela; ninguém escape dela, pagai-lhe conforme sua obra; conforme tudo o que ela fez, fazei-lhe; porque agiu arrogantemente contra o SENHOR, contra o Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 30, 'Portanto seus rapazes cairão em suas ruas; e todos os seus homens de guerra serão exterminados naquele dia,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 31, 'Eis que eu contra ti, ó soberbo,diz o Senhor DEUS dos exércitos; porque veio o teu dia, o tempo em que te castigarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 32, 'E o soberbo tropeçará e cairá, e ninguém haverá que o levante; e acenderei fogo em suas cidades, que consumirá todos os seus arredores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 33, 'Assim diz o SENHOR dos exércitos: Os filhos de Israel e os filhos de Judá juntamente foram oprimidos; e todos os que os tomaram cativos os detiveram; recusaram-se soltá-los.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 34, 'Porém o Redentor deles é forte; EU-SOU dos exércitos é o seu nome; certamente defenderá a causa deles, para dar descanso à terra, e incomodar os moradores da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 35, 'Espada [virá] sobre os caldeus, diz o SENHOR, e sobre os moradores da Babilônia, sobre seus príncipes, e sobre seus sábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 36, 'Espada [virá] sobre os adivinhos, e se tornarão tolos; espada [virá] sobre seus guerreiros, e perderão as forças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 37, 'Espada [virá] sobre seus cavalos, sobre seus carros, e sobre todo os estrangeiros que estão no meio dela, e serão como mulheres; espada [virá] sobre seus tesouros, e serão saqueados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 38, 'Sequidão [virá] sobre suas águas, e se secarão; pois é terra de idolatrias, e se enlouquecem por [seus] ídolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 39, 'Por isso [nela] habitarão animais selvagens do deserto com hienas; habitarão também nela filhotes de avestruz; e nunca mais será habitada, nem servirá de morada geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 40, 'Assim como Deus destruiu Sodoma, Gomorra e suas cidades vizinhas,diz o SENHOR, assim também não habitará ali homem, nem filho de homem a morará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 41, 'Eis que um povo vem do norte; e uma grande nação, e muitos reis se levantarão dos lugares distantes da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 42, 'Eles manejam arco e lança; são cruéis, e não terão compaixão; sua voz soará como o mar, e montarão sobre cavalos; ficarão em posição como de homem para a batalha, contra ti, ó filha da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 43, 'O rei da Babilônia ouviu a notícia deles, e suas mãos perderam as forças; tomado foi por angústia e dor, como mulher de parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 44, 'Eis que como leão subirá da mata do Jordão contra a morada do forte; pois repentinamente o farei correr dali. E ordenarei contra ela a quem eu escolher; pois quem é semelhante a mim? E quem manda em mim? Ou quem é o pastor que pode subsistir diante de mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 45, 'Portanto ouvi o conselho do SENHOR, que decretou contra a Babilônia; e seus pensamentos, que ele determinou sobre a terra dos caldeus: Certamente os menores do rebanho serão arrastados, certamente destruirá sua habitação com deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 50, 46, 'Do ruído da tomada da Babilônia a terra tremeu, e o grito se ouviu entre as nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 1, 'Assim diz o SENHOR: Eis que eu levanto um vento destruidor contra a Babilônia, e contra os moradores de Lebe-Camai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 2, 'E enviarei padejadores à Babilônia, que a padejarão, e esvaziarão sua terra; porque virão contra ela por todos os lados no dia da calamidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 3, 'Que o flecheiro não arme o seu arco, nem deixes que ponham sua couraça; não poupeis a seus rapazes, destruí todo o seu exército.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 4, 'E os mortos cairão na terra dos caldeus, e os perfurados em suas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 5, 'Porque Israel e Judá não foram abandonados por seu Deus, o SENHOR dos exércitos, ainda que sua terra foi cheia de pecado contra o Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 6, 'Fugi do meio de Babilônia, e livrai cada um sua alma; não pereçais por causa de sua maldade; pois é tempo de vingança do SENHOR, em que ele lhe dará o pagamento dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 7, 'A Babilônia era um copo de ouro na mão do SENHOR, que embriagava toda a terra; de seu vinho beberam as nações; por isso as nações se enlouqueceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 8, 'Repentinamente Babilônia caiu, e se despedaçou: uivai por ela; tomai bálsamo para sua dor, talvez sare.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 9, 'Sararíamos Babilônia, porém ela não se sarou; deixai-a, e vamo-nos cada um a sua terra; pois seu julgamento chegou até o céu, e subiu até as nuvens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 10, 'O SENHOR trouxe à luz nossas justiças; vinde, e contemos em Sião a obra do SENHOR nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 11, 'Limpai as flechas, preparai os escudos; o SENHOR levantou o espírito dos reis da Média; pois seu pensamento é contra Babilônia para destruí-la; pois esta é vingança do SENHOR, a vingança de seu templo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 12, 'Levantai bandeira sobre os muros da Babilônia, reforçai a guarda, ponde vigilantes, preparai ciladas; pois assim o SENHOR tanto planejou como fez o que disse sobre os moradores de Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 13, 'Tu que habitas sobre muitas águas, rica em tesouros, chegou o teu fim, o limite de tua ganância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 14, 'O SENHOR dos exércitos jurou por si mesmo, [dizendo] : Eu te encherei de homens como de gafanhotos, que darão gritos [de guerra] contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 15, 'Ele é o que fez a terra com sua força, o que estabeleceu o mundo com sua sabedoria, e estendeu os céus com seu entendimento;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 16, 'Quando ele dá sua voz, há um grande estrondo de águas no céu, e faz subir as nuvens desde os confins da terra; ele faz os relâmpagos com a chuva, e tira o vento de seus tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 17, 'Todo homem tem se tornado bruto, e sem conhecimento; envergonha-se todo artífice da imagem de escultura, porque sua imagem de fundição é mentira, e não há espírito nelas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 18, 'Elas são inúteis, obra de enganos; no tempo de seu castigo perecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 19, 'A porção de Jacó não é como eles; pois ele é o Formador de tudo; e Israel é a vara de sua herança; EU-SOU dos exércitos é o seu nome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 20, 'Tu és para mim um martelo, [e] armas de guerra; contigo despedaçarei nações, e contigo destruirei reinos;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 21, 'Contigo despedaçarei o cavalo e seus cavaleiro, contigo despedaçarei a carruagem, e os que nela sobem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 22, 'Contigo despedaçarei o homem e a mulher, contigo despedaçarei o velho e o jovem, contigo despedaçarei o rapaz e a moça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 23, 'Contigo despedaçarei o pastor e seu rebanho; contigo despedaçarei o lavrador e suas juntas [de bois] ; e contigo despedaçarei governadores e príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 24, 'Mas retribuirei à Babilônia e a todos os moradores da Caldeia todo a sua maldade, que fizeram em Sião diante de vossos olhos,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 25, 'Eis que eu sou contra ti, ó monte destruidor, que destróis toda a terra,diz o SENHOR, e estenderei minha mão contra ti, e te farei rolar das rochas, e te tonarei um monte queimado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 26, 'E não tomarão de ti pedra para esquina, nem pedra para fundamentos; porque te tornarás em assolações perpétuas,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 27, 'Levantai bandeira na terra, tocai trombeta entre as nações, preparai nações contra ela; convocai contra ela os reinos de Ararate, Mini, e Asquenaz; ordenai contra ela capitães, fazei subir cavalos como gafanhotos eriçados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 28, 'Preparai contra ela as nações; os reis da Média, seus capitães, e todos seus chefes, e também toda a terra em que eles governam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 29, 'Então a terra tremerá, e se afligirá; porque todos os pensamentos do SENHOR estão firmes contra a Babilônia, para tornar a terra de Babilônia em desolação, de modo que não haja morador [nela] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 30, 'Os guerreiros de Babilônia pararam de lutar, ficaram-se nas fortalezas; faltou-lhes sua força, tornaram-se como mulheres; incendiaram-se suas casas, quebraram-se seus ferrolhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 31, 'Corredor se encontrará com corredor, mensageiro se encontrará com mensageiro, para anunciar ao rei de Babilônia que sua cidade é tomada por todas os lados;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 32, 'E os vaus foram tomados, os canaviais foram queimados a fogo, e os homens de guerra foram assombrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 33, 'Pois assim diz o SENHOR dos exércitos, Deus de Israel: A filha de Babilônia é como uma eira; já é tempo de trilhá-la; daqui a pouco lhe virá o tempo da ceifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 34, 'Comeu-me, esmagou-me Nabucodonosor rei de Babilônia; tornou-me como um vaso vazio, tragou-me como um chacal, seu ventre se encheu do que eu tinha de melhor, e me lançou fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 35, 'A violência feita contra mim e minha carne [venha] sobre a Babilônia, dirá a moradora de Sião; e meu sangue sobre os moradores da Caldeia, dirá Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 36, 'Portanto assim diz o SENHOR: Eis que eu defenderei a tua causa, e vingarei por ti; secarei seu mar, e farei que seu manancial fique seco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 37, 'E Babilônia se tornará em amontoados, em morada de chacais, espanto e assovio, sem morador algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 38, 'Juntamente rugirão como leões; como filhotes de leões bramarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 39, 'Quando estiverem esquentados, eu lhes porei seus banquetes, e farei com que se embriaguem, para que se alegrem, e durmam um sono eterno, e não despertem,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 40, 'Eu os levarei abaixo como cordeiros ao matadouro, como carneiros e bodes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 41, 'Como foi capturada Sesaque, e tomada a que era o louvor de toda a terra! Como Babilônia se tornou em espanto entre as nações!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 42, 'O mar subiu sobre a Babilônia; pela multidão de suas ondas foi coberta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 43, 'Suas cidades se tornaram desoladas, uma terra seca e deserta, terra que ninguém habita, nem filho de homem passa por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 44, 'E punirei a Bel na Babilônia, e tirarei de sua boca o que tragou; e nunca mais as nações virão a ele; e o muro da Babilônia cairá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 45, 'Saí do meio dela, ó povo meu, e livrai cada um sua alma do ardor da ira do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 46, 'E para que vosso coração não perca as forças, e tenhais medo por causa das notícias que forem ouvidas pela terra; pois em um ano virá notícias, e depois em outro ano mais notícias; e haverá violência na terra, dominador sobre dominador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 47, 'Portanto eis que vêm dias em que punirei as imagens de escultura da Babilônia, e toda a sua terra será envergonhada, e todos seus mortos cairão no meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 48, 'E os céus, a terra, e tudo quanto neles há, cantarão vitória sobre a Babilônia; porque do norte virão destruidores contra ela,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 49, 'Pois Babilônia cairá por causa dos mortos de Israel, assim como por causa da Babilônia caíram mortos de toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 50, 'Vós que escapastes do espada, ide embora, não pareis; lembrai-vos do SENHOR até longe, e Jerusalém venha à vossa mente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 51, '[Direis, porém] : Estamos envergonhados, porque ouvimos a humilhação; a vergonha cobriu nossos rostos, porque vieram estrangeiros contra os santuários da casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 52, 'Portanto eis que vêm dias,diz o SENHOR, em que punirei suas imagens de escultura, e em toda a sua terra gemerão os feridos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 53, 'Mesmo se a Babilônia subisse ao céu e se fortificasse no alto seu poder, ainda assim de mim virão destruidores contra ela,diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 54, '[Ouve-se] som de gritos da Babilônia, e grande quebrantamento da terra dos caldeus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 55, 'Pois o SENHOR destrói a Babilônia, e eliminará dela [seu] grande ruído; e suas ondas bramarão, como muitas águas será o ruído da voz deles:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 56, 'Pois o destruidor vem contra ela, contra Babilônia; seus guerreiros serão presos, o arco deles será quebrado; porque o SENHOR, Deus de retribuições, certamente dará a pagamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 57, 'E embriagarei a seus príncipes e seus sábios, a seus governadores, seus chefes e seus guerreiros; e dormirão sonho perpétuo, e não despertarão, diz o Rei, cujo nome é EU-SOU dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 58, 'Assim diz o SENHOR dos exércitos: Os largos muros da Babilônia serão derrubado por completo, e suas altas portas serão incendiadas a fogo; os povos trabalharão para nada, as nações para o fogo, e se cansarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 59, 'Palavra que o profeta Jeremias enviou a Seraías, filho de Nerias, filho de Maasias, quando ele foi com Zedequias rei de Judá para a Babilônia, no quarto ano de seu reinado. E Seraías era o camareiro-chefe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 60, 'Escreveu, pois, Jeremias em um livro todo o mal que viria sobre a Babilônia, todas estas palavras que estavam escritas contra a Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 61, 'E Jeremias disse a Seraías: Quando chegares à Babilônia, tu deves ler e dizer todas estas palavras,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 62, 'Então dirás: Ó SENHOR, tu falaste sobre este lugar, que o cortarias fora, até não ficar nele morador, nem homem nem animal, e que se tornaria em desolação perpétua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 63, 'E será que, quando acabares de ler este livro, tu o atarás a uma pedra, e o lançarás no meio do Eufrates,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 51, 64, 'E dirás: Assim Babilônia será afundada, e não se levantará da calamidade que eu trago sobre ela; e se cansarão. Até aqui são as palavras de Jeremias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 1, 'Zedequias era de idade de vinte e um anos quando começou a reinar, e reinou onze anos em Jerusalém. Sua mãe se chamava Hamutal, filha de Jeremias, de Libna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 2, 'E ele fez o que era mal aos olhos do SENHOR, conforme tudo o que Jeoaquim fizera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 3, 'E por isso a ira do SENHOR foi contra Jerusalém e Judá, até que ele os expulsou de sua presença; assim Zedequias se rebelou contra o rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 4, 'E aconteceu no nono ano de seu reinado, no decimo mês, aos dez dias do mês, que veio Nabucodonosor rei da Babilônia, ele e todo seu exército, contra Jerusalém, e contra ela montaram um acampamento, e ao redor por todos os lados levantaram cercos contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 5, 'Assim a cidade esteve cercada até o décimo primeiro ano do rei Zedequias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 6, 'No quarto mês, aos nove do mês, quando a fome havia dominado a cidade, até não haver pão para o povo da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 7, 'Então a cidade foi arrombada, e todos os homens de guerra fugiram, e saíram da cidade de noite, pelo caminho de porta de entre os dois muros, que era perto do jardim do rei, e foram-se pelo caminho de Arabá, enquanto os caldeus estavam ao redor da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 8, 'Porém o exército dos caldeus perseguiu o rei, e alcançaram a Zedequias nas planícies de Jericó; e todo o seu exército se dispersou dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 9, 'Então prenderam ao rei, e fizeram-lhe vir ao rei de Babilônia, a Ribla na terra de Hamate, onde pronunciou sentença contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 10, 'E o rei da Babilônia degolou os filhos de Zedequias diante de seus olhos; e também degolou a todos os príncipes de Judá em Ribla.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 11, 'Mas Zedequias porém cegou os olhos, e o acorrentou com grilhões de bronze; e o rei da Babilônia o levou à Babilônia, e o pôs na casa do cárcere até o dia de sua morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 12, 'E no quinto mês, aos dez do mês (que era o décimo nono ano do reinado de Nabucodonosor, rei de Babilônia), Nebuzaradã, capitão da guarda, que servia diante do rei de Babilônia, veio a Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 13, 'E queimou a casa do SENHOR, a casa do rei, e todas as casas de Jerusalém; e queimou com fogo todo grande edifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 14, 'E todo o exército dos caldeus que estava com o capitão da guarda derrubou todos os muros que estavam ao redor de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 15, 'E Nebuzaradã, capitão da guarda, levou presos os pobres do povo, e ao demais do povo, que restaram na cidade, e os rebeldes que se haviam se rendido ao rei de Babilônia, e todo o resto dos artesãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 16, 'Mas Nebuzaradã, capitão da guarda, deixou dos mais pobres daquela terra para serem cultivadores de vinhas e lavradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 17, 'E os caldeus quebraram as colunas de bronze que estavam na casa do SENHOR, as bases, e o mar de bronze que estavam na casa do SENHOR, e levaram todo o bronze à Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 18, 'Tomaram também os caldeirões, as pás, os cortadores de pavios, as bacias, os pratos, e todos os vasos de bronze com que faziam o serviço [no templo] ;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 19, 'E o capitão da guarda tomou os copos, os incensários, as bacias, as panelas, os castiçais, os pratos, e vasos de ofertas de líquidos: tudo o que era de ouro ou de prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 20, 'As duas colunas, o mar, e os doze bois de bronze que estavam debaixo das bases, que o rei Salomão tinha feito na casa do SENHOR. não se podia pesar o bronze de todos estes vasos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 21, 'Quanto às colunas, a altura de cada coluna era de dezoito côvados, e um fio de doze côvados a rodeava; e sua espessura era de quatro dedos, [e] era oca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 22, 'E [tinha] sobre si um capitel de bronze, e a altura do capitel era de cinco côvados, com uma rede e romãs ao redor do capitel, tudo de bronze; e semelhante a esta era o da segunda coluna, com [suas] romãs.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 23, 'E havia noventa e seis romãs em cada lado; ao todo elas eram cem sobre a rede ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 24, 'O capitão da guarda também tomou a Seraías o sacerdote principal, e a Sofonias o segundo sacerdote, e três guardas da porta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 25, 'E da cidade tomou a um eunuco que era comandante sobre os homens de guerra, e a sete homens que serviam na presença do rei, que se acharam na cidade; e também ao principal escrivão do exército, que registrava o povo da terra para a guerra; e a sessenta homens do povo da terra, que se acharam no meio da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 26, 'Então Nebuzaradã, capitão da guarda, os tomou, e os levou ao rei de Babilônia, a Ribla.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 27, 'E o rei de Babilônia os feriu e os matou em Ribla na terra de Hamate. Assim Judá foi levado cativo de sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 28, 'Este é o povo que Nabucodonosor levou cativo; no sétimo ano, três mil e vinte e três judeus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 29, 'No décimo oitavo ano Nabucodonosor, levou cativas de Jerusalém oitocentas e trinta e duas pessoas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 30, 'No vigésimo terceiro ano de Nabucodonosor, Nebuzaradã capitão da guarda levou cativas setecentas e quarenta e cinco pessoas dos judeus; no total foram quatro mil e seiscentas pessoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 31, 'Sucedeu, pois, no trigésimo sétimo ano de cativeiro de Joaquim rei de Judá, no décimo segundo mês, aos vinte e cinco do mês, que Evil-Merodaque, rei da Babilônia, no [primeiro] ano de seu reinado, concedeu perdão a Joaquim rei de Judá, e o tirou da casa de prisão;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 32, 'E falou com ele benignamente; e pôs sua cadeira com mais honra do que as cadeiras dos reis que estavam com ele em Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 33, 'E mudou-lhe também as roupas de sua prisão, e continuamente comeu pão diante dele, todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 24, 'Jeremias', 'Jr', 52, 34, 'E continuamente foi-lhe dada provisão pelo rei da Babilônia, uma porção diária, até o dia de sua morte, por todos os dias de sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 1, 'Como se senta solitária a cidade que era tão populosa! A grande entre as nações tornou-se como viúva, a senhora de províncias passou a ser escrava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 2, 'Amargamente chora na noite, suas lágrimas em seu rosto; entre todos os seus amantes não há quem a console; todos os seus amigos a traíram, inimigos se tornaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 3, 'Judá foi ao cativeiro com aflição e grande servidão; ela habita entre as nações, mas não acha descanso; todos os seus perseguidores a alcançam em meio ao aperto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 4, 'Os caminhos de Sião estão em pranto, pois ninguém vem aos festivais; todas as suas portas estão desertas, seus sacerdotes gemem, suas virgens se afligem, e ela sofre de amargura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 5, 'Seus oponentes estão no comando, seus inimigos prosperam; pois o SENHOR a afligiu por causa das suas muitas transgressões; suas crianças foram em cativeiro adiante do adversário.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 6, 'Partiu-se toda a beleza da filha de Sião; seus líderes estão como cervos, não acham pasto algum; eles andam fracos, fugindo do perseguidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 7, 'Nos dias da sua aflição, e de suas andanças perdidas, Jerusalém lembra-se de todas as suas preciosidades, que tinha nos tempos antigos; quando seu povo caiu na mão do adversário, não houve quem a ajudasse; os adversários a viram, e zombaram da sua queda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 8, 'Jerusalém pecou gravemente; por isso ela se tornou impura; todos os que a honravam a desprezam, porque viram a sua nudez; ela geme, e se vira para trás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 9, 'Sua imundície estava até nas roupas; nunca se importou com o seu futuro ; por isso caiu espantosamente, sem ter quem a consolasse. Olha, SENHOR, a minha aflição, porque o inimigo está engrandecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 10, 'O adversário tomou todas as suas coisas de valor; ela viu as nações entrarem no seu templo - aquelas que proibiste de entrarem na tua congregação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 11, 'Todo o seu povo anda suspirando em busca de pão; trocaram todas os seus bens por comida a fim de sobreviverem. Olha, SENHOR, e vê que estou desprezada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 12, 'Todos vós que estais passando, não vos [importais] ? Olhai, e vede se há dor como a minha, que me foi imposta, que o SENHOR me afligiu no dia da sua ira ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 13, 'Desde o alto ele enviou fogo em meus ossos, o qual os dominou; ele estendeu uma rede a meus pés, fez-me voltar para trás; tornou-me assolada, sofrendo dores o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 14, 'O jugo de minhas transgressões está amarrado por sua mão, elas estão ligadas, postas sobre o meu pescoço; ele abateu minhas forças. O Senhor me entregou nas suas mãos daqueles contra quem não posso me levantar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 15, 'O Senhor derrotou todos os meus fortes em meio de mim; convocou contra mim um ajuntamento para quebrar os meus rapazes; o Senhor tem pisado a virgem filha de Judá como [se fosse] em uma prensa de uvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 16, 'Por estas coisas que eu choro; meus olhos, de meus olhos correm águas; pois afastou-se de mim consolador que daria descanso à minha alma: meus filhos estão desolados, porque o inimigo prevaleceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 17, 'Sião estendeu suas mãos, não há quem a console; o SENHOR deu ordens contra Jacó, para que seus inimigos o cercassem: Jerusalém se tornou imunda entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 18, 'O SENHOR é justo; eu que me rebelei contra sua boca. Ouvi, pois, todos os povos, e vede minha dor; minhas virgens e meus rapazes foram em cativeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 19, 'Clamei a meus amantes, porém eles me enganaram; meus sacerdotes e meus anciãos pereceram na cidade; pois buscam comida para si tentarem sobreviver. )'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 20, 'Olha, SENHOR, que estou angustiada; tormentam-se minhas entranhas, meu coração está transtornado em meio de mim, pois gravemente me rebelei; de fora desfilhou [-me] a espada, de dentro está como a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 21, 'Eles me ouvem gemendo, [porém] não tenho consolador. Todos meus inimigos, quando ouvem minha aflição se alegram, pois tu o fizeste. Quando tu trouxeres o dia que anunciaste, eles serão como eu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 1, 22, 'Toda a maldade deles venha diante de ti, e faze com eles assim como fizeste comigo por causa de todas as minhas transgressões; pois meus gemidos são muitos, e meu coração está desfalecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 1, 'Como o Senhor cobriu a filha de Sião com sua ira! Ele derrubou a formosura de Israel do céu à terra, e não se lembrou do estrado de seus pés no dia de sua ira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 2, 'O Senhor, destruiu sem compaixão todas as moradas de Jacó; derrubou em seu furor as fortalezas da filha de Judá, desonrou o reino e seus príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 3, 'Cortou no furor de sua ira todo o poder de Israel; tirou sua mão direita de diante do inimigo; e se acendeu contra Jacó como labareda de fogo que consome ao redor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 4, 'Armou seu arco como inimigo, pôs sua mão direita como adversário, e matou todas as coisas agradáveis à vista; derramou sua indignação como fogo na tenda da filha de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 5, 'O Senhor tornou-se como inimigo, destruiu a Israel; destruiu todos os seus palácios, arruinou as suas fortalezas; e multiplicou na filha de Judá a lamentação e a tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 6, 'E com violência arrancou sua tenda, como [se fosse] de uma horta, destruiu o lugar de sua congregação; o SENHOR fez esquecer em Sião as solenidades e os sábados, E tem lançado no furor de sua ira rei e sacerdote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 7, 'O Senhor rejeitou seu altar, detestou seu santuário, entregou na mão do inimigo os muros de seus palácios; levantaram gritaria na casa do SENHOR como em dia de festa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 8, 'O SENHOR determinou destruir o muro da filha de Sião; estendeu o cordel, não deteve sua mão de destruir; tornou em lamento o antemuro e o muro; juntamente foram destruídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 9, 'Suas portas foram lançadas por terra, destruiu e quebrou seus ferrolhos; sua rei e seus príncipes estão entre as nações onde não há a Lei; nem seus profetas acham visão alguma do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 10, 'Sentados na terra [e] calados estão os anciãos da filha de Sião; lançaram pó sobre suas cabeças, vestiram-se de saco; as virgens de Jerusalém baixaram suas cabeças à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 11, 'Meus olhos se consumiram de lágrimas, atormentam-se minhas entranhas; meu fígado se derramou por terra por causa do quebrantamento da filha de meu povo, porque crianças e bebês de mama desfalecem pelas ruas da cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 12, 'Eles dizem às suas mães: Onde está o trigo e o vinho?, enquanto desfalecem como feridos pelas ruas da cidade, derramando suas almas no colo de suas mães.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 13, 'Que testemunho te trarei, ou a quem te compararei, ó filha de Jerusalém? A quem te assemelharei para te consolar, ó virgem, filha de Sião? Pois teu quebrantamento é tão grande quanto o mar; quem te curará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 14, 'Teus profetas previram para ti futilidades e enganos; e não expuseram tua maldade para evitar teu cativeiro; em vez disso te predisseram profecias mentirosas e ilusórias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 15, 'Todos os que passam pelo caminho, batem palmas [para zombar] de ti; assoviaram, e moveram suas cabeças por causa da filha de Jerusalém, dizendo: É esta a cidade que diziam ser a perfeita beleza, a alegria de toda a terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 16, 'Todos os teus inimigos abrem suas bocas contra ti, assoviam, e rangem os dentes; dizem: Nós [a] devoramos; pois este é o dia que esperávamos; nós o achamos, [e] o vimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 17, 'O SENHOR fez o que tinha determinado; cumpriu sua palavra que ele havia mandado desde os dias antigos; destruiu sem ter compaixão; e alegrou o inimigo sobre ti, e levantou o poder de teus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 18, 'O coração deles clamou ao Senhor. Ó muralha da filha de Sião, derrama lágrimas como um ribeiro dia e noite; não te dês descanso, nem cessem as meninas de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 19, 'Levanta-te, grita de noite, no começo das vigílias; derrama teu coração como águas diante da presença do Senhor; levanta tuas mãos a ele pela vida de tuas criancinhas, que desfalecem de fome nas entradas de todas as ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 20, 'Olha, SENHOR, e considera a quem fizeste de tal modo; por acaso as mulheres comerão do seu [próprio] fruto, as criancinhas que carregam nos braços? Por acaso serão o sacerdote e o profeta mortos no santuário do Senhor?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 21, 'Jovens e velhos jazem por [pelas] ruas; minhas virgens e meus rapazes caíram à espada; tu [os] mataste no dia de tua ira, degolaste sem ter compaixão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 2, 22, 'Convocaste meus temores ao redor, como se fosse um dia solene; não houve quem escapasse no dia do ira do SENHOR, nem que restasse vivo; aos que criei e sustentei, meu inimigo os consumiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 1, 'Eu sou o homem que viu a aflição pela vara de seu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 2, 'Guiou-me e levou-me a trevas, e não à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 3, 'Com certeza se virou contra mim, revirou sua mão o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 4, 'Fez envelhecer minha carne e minha pele, quebrou meus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 5, 'Edificou contra mim, e cercou [-me] de fel e de trabalho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 6, 'Fez-me habitar em lugares escuros, como os que já morrera há muito tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 7, 'Cercou-me por todos lados, e não posso sair; tornou pesados os meus grilhões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 8, 'Até quando clamo e dou vozes, fechou [os ouvidos] à minha oração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 9, 'Cercou meus caminhos com pedras lavradas, retorceu as minhas veredas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 10, 'Foi para mim como um urso que espia, como um leão escondido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 11, 'Desviou meus caminhos, e fez-me em pedaços; deixou-me desolado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 12, 'Armou seu arco, e me pôs como alvo para a flecha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 13, 'Fez entrar em meus rins as flechas de sua aljava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 14, 'Servi de escárnio a todo o meu povo, de canção ridícula deles o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 15, 'Fartou-me de amarguras, embebedou-me de absinto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 16, 'Quebrou os meus dentes com cascalho, cobriu-me de cinzas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 17, 'E afastou minha alma da paz, fez-me esquecer da boa vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 18, 'Então eu disse: Pereceram minha força e minha esperança no SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 19, 'Lembra-te da minha aflição e do meu sofrimento, do absinto e do fel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 20, 'Minha alma se lembra e se abate em mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 21, 'Disto me recordarei na minha mente, por isso terei esperança:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 22, 'É pelas bondades do SENHOR que não somos consumidos, porque suas misericórdias não têm fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 23, 'Elas são novas a cada manhã; grande é a tua fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 24, 'O SENHOR é minha porção, diz a minha alma; portanto nele esperarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 25, 'Bom é o SENHOR para os que nele esperam, para a alma que o busca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 26, 'É bom esperar e tranquilo aguardar a salvação do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 27, 'É bom ao homem levar o jugo em sua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 28, 'Sente-se só, e fique quieto; pois ele o pôs sobre si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 29, 'Ponha sua boca no pó; talvez haja esperança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 30, 'Dê a face ao que o ferir; farte-se de insultos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 31, 'Pois o Senhor não rejeitará para sempre:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 32, 'Mesmo que cause aflição, ele também se compadecerá segundo a grandeza de suas misericórdias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 33, 'Pois não é sua vontade afligir nem entristecer os filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 34, 'Esmagar debaixo de seus pés a todos os prisioneiros da terra,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 35, 'Perverter o direito do homem diante da presença do Altíssimo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 36, 'Prejudicar ao homem em sua causa: o Senhor não aprova ) [tais coisas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 37, 'Quem é que pode fazer suceder [algo] que diz, se o Senhor não tiver mandado?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 38, 'Por acaso da boca do Altíssimo não sai tanto a maldição como a bênção?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 39, 'Por que o homem vivente se queixa da punição de seus próprios pecados?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 40, 'Examinemos nossos caminhos, investiguemos, e nos voltemos ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 41, 'Levantemos nossos corações e as mãos a Deus nos céus,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 42, '[Dizendo:] Nós transgredimos e fomos rebeldes; tu não perdoaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 43, 'Cobriste-te de ira, e nos perseguiste; mataste sem teres compaixão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 44, 'Cobriste-te de nuvens, para que [nossa] oração não passasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 45, 'Tu nos tornaste como escória e rejeito no meio dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 46, 'Todos os nossos inimigos abriram sua boca contra nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 47, 'Medo e cova vieram sobre nós, devastação e destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 48, 'Rios de águas correm de meus olhos, por causa da destruição da filha de meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 49, 'Meus olhos destilam, e não cessam; não haverá descanso,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 50, 'Até que o SENHOR preste atenção, e veja desde os céus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 51, 'Meus olhos afligem minha alma, por causa de todas as filhas de minha cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 52, 'Sem motivo meus inimigos me caçam como a um passarinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 53, 'Tentaram tirar minha vida na masmorra, e lançaram pedras sobre mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 54, 'As águas inundaram sobre minha cabeça; eu disse: É o meu fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 55, 'Invoquei o teu nome, SENHOR, desde a cova profunda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 56, 'Ouviste minha voz: não escondas o teu ouvido ao meu suspiro, ao meu clamor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 57, 'Tu te achegaste no dia em que te invoquei; disseste: Não temas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 58, 'Defendeste, Senhor, as causas de minha alma; redimiste minha vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 59, 'Viste, SENHOR, a maldade que me fizeram; julga minha causa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 60, 'Viste toda a vingança deles, todos os seus pensamentos contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 61, 'Ouvido os seus insultos, ó SENHOR, todos os seus pensamentos contra mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 62, 'As coisas ditas pelos que se levantam contra mim, e seu planos contra mim o dia todo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 63, 'Olha para tudo quanto eles fazem; com canções zombam de mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 64, 'Retribui-lhes, SENHOR, conforme a obra de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 65, 'Dá-lhes angústia de coração, tua maldição a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 3, 66, 'Persegue-os com ira, e destrua-os de debaixo dos céus do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 1, 'Como se escureceu o ouro! Como mudou o bom e fino ouro! As pedras do Santuário estão espalhadas pelas esquinas de todas as ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 2, 'Os preciosos filhos de Sião, estimados como o ouro puro, como [agora] são considerados como vasos de barro, obra das mãos de oleiro!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 3, 'Até os chacais dão o peito para amamentar a seus filhotes; [porém] a filha de meu povo se tornou cruel, como os avestruzes no deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 4, 'Por causa da sede a língua da criança de peito se grudou a seu céu da boca; os meninos pedem pão, e ninguém há lhes reparta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 5, 'Os que comiam das melhores iguarias, [agora] desfalecem nas ruas; os que se criaram em carmesim abraçam o lixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 6, 'Pois maior é o castigo da filha de meu povo do que o [do] pecado de Sodoma, Que foi transtornada em um momento, e não assentaram sobre ela companhias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 7, 'Seus nazireus eram mais alvos que a neve, mais brancos que o leite. Seus corpos eram mais avermelhados que rubis, [e] mais polidos que a safira;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 8, '[Mas agora] sua aparência se escureceu mais que o carvão; não são mais reconhecidos nas ruas; sua pele está apegada a seus ossos, ficou seca como um pau.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 9, 'Mais felizes foram os mortos pela espada do que os mortos pela fome; porque estes se abatem traspassados pela [falta] dos frutos do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 10, 'As mãos das mulheres compassivas cozeram a seus filhos; serviram-lhes de comida na destruição da filha de meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 11, 'O SENHOR cumpriu o seu furor, derramou o ardor de sua ira; e acendeu fogo em Sião, que consumiu seus fundamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 12, 'Nem os reis da terra, nem todos os que habitam no mundo, criam que o adversário e o inimigo entraria pelas portas de Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 13, '[Assim] foi por causa dos pecados de seus profetas, por causa das maldades de seus sacerdotes, que derramaram o sangue dos justos em meio dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 14, 'Titubearam [como] cegos nas ruas, andaram contaminados de sangue, de maneira que ninguém podia tocar suas vestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 15, 'Gritavam-lhes: Afastai-vos, imundos! Afastai-vos, afastai-vos, não toqueis. Quando fugiram e andaram sem rumo, foi dito entre as nações: Aqui não morarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 16, 'A face do SENHOR os dispersou, não os olhará mais: não respeitaram a face dos sacerdotes, nem tiveram compaixão dos velhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 17, 'Quanto a nós, desfaleceram-se nossos olhos [esperando] por socorro para nós; aguardávamos atentamente uma nação que não podia salvar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 18, 'Caçaram nossos passos, de modo que não podíamos andar por nossas ruas; achegou-se o nosso fim, nossos dias se completaram, pois nosso fim veio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 19, 'Nossos perseguidores foram mais velozes que as águias do céu; sobre os montes nos perseguiram, no deserto armaram ciladas para nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 20, 'O fôlego de nossas narinas, o ungido do SENHOR, do qual dizíamos: Abaixo de sua sombra teremos vida entre as nações; foi preso em suas covas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 21, 'Goza-te e alegra-te, filha de Edom, que habitas na terra de Uz: porém o cálice também passará por ti; tu te embriagarás, e te desnudarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 4, 22, 'Cumpriu-se o castigo por tua maldade, ó filha de Sião; nunca mais te levará em cativeiro. Ele punirá tua maldade, ó filha de Edom; revelará os teus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 1, 'Lembra-te, SENHOR, do que tem nos acontecido; presta atenção e olha nossa humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 2, 'Nossa herança passou a ser de estrangeiros, nossas casas de forasteiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 3, 'Órfãos somos sem pai, nossas mães são como viúvas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 4, 'Bebemos nossa água por dinheiro; nossa lenha temos que pagar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 5, 'Perseguição sofremos sobre nossos pescoços; estamos cansados, mas não temos descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 6, 'Nós nos rendemos aos egípcios e aos assírios para nos saciarmos de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 7, 'Nossos pais pecaram, e não existem mais; porém nós levamos seus castigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 8, 'Servos passaram a nos dominar; ninguém há que [nos] livre de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 9, 'Com risco de vida trazemos nosso pão, por causa da espada do deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 10, 'Nossa pele se tornou negra como um forno, por causa do ardor da fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 11, 'Abusaram das mulheres em Sião, das virgens nas cidades de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 12, 'Os príncipes foram enforcados por sua mãos; não respeitaram as faces dos velhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 13, 'Levaram os rapazes para moer, e os moços caíram debaixo da lenha [que carregavam] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 14, 'Os anciãos deixaram de [se sentarem] junto as portas, os rapazes de suas canções.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 15, 'Acabou a alegria de nosso coração; nossa dança se tornou em luto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 16, 'Caiu a coroa de nossa cabeça; ai agora de nós, porque pecamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 17, 'Por isso nosso coração ficou fraco, por isso nossos olhos escureceram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 18, 'Por causa do monte de Sião, que está desolado; raposas andam nele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 19, 'Tu, SENHOR, permanecerás para sempre; [e] teu trono de geração após geração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 20, 'Por que te esquecerias de nós para sempre e nos abandonarias por tanto tempo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 21, 'Converte-nos, SENHOR, a ti, e seremos convertidos; renova o nossos dias como antes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 25, 'Lamentações', 'Lm', 5, 22, 'A não ser que tenhas nos rejeitado totalmente, e estejas enfurecido contra nós ao extremo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 1, 'E sucedeu que, aos trinta anos, no quarto [mês] , aos cinco do mês, estando eu em meio dos exilados, junto ao rio Quebar, os céus se abriram, e vi visões de Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 2, 'Aos cinco do mês, que foi no quinto ano do cativeiro do rei Joaquim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 3, 'verdadeiramente veio a palavra do SENHOR ao sacerdote Ezequiel, filho de Buzi, na terra dos caldeus, junto ao rio Quebar; e ali a mão do SENHOR esteve sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 4, 'Então olhei, e eis que um vento tempestuoso vinha do norte, uma grande nuvem, e um fogo incandescente, e ao seu redor um resplendor, e no meio do fogo uma coisa que parecia como de âmbar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 5, 'E no meio dela havia a semelhança de quatro animais; e esta era sua aparência; eles tinham semelhança humana.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 6, 'E cada um tinha quatro rostos, e cada um quatro asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 7, 'E suas pernas eram retas, e a planta de seus pés como a planta de pé de bezerro; e reluziam como o bronze polido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 8, 'E [tinham] mãos humanas debaixo de suas asas, em seus quatro lados; [assim] os quatro [tinham] seus rostos e suas asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 9, 'Suas asas se juntavam umas às outras. Não viravam quando se moviam; cada um andava na direção de seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 10, 'E a aparência de seus rostos era [como] rosto de homem; e rosto de leão à direita nos quatro; e à esquerda rosto de boi nos quatro; também havia nos quatro um rosto de águia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 11, '[Assim] eram seus rostos. E suas asas estavam estendidas por cima, cada um duas, as quais se juntavam; e as outras duas cobriam seus corpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 12, 'E cada um se movia na direção de seu rosto; para onde o espírito se dirigia, eles iam; não viravam quando se moviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 13, 'Quanto à semelhança dos animais, sua aparência era como pedaços de carvão acesos, como aparência de tochas acesas; o fogo se movia entre os animais; e brilhava intensamente, e do fogo saíam relâmpagos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 14, 'E os animais corriam e voltavam, à semelhança de relâmpagos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 15, 'E enquanto eu estava vendo os animais, eis que uma roda estava na terra junto aos animais, junto a seus quatro rostos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 16, 'E a aparência das rodas, e sua feitura, era como da cor do berilo; e as quatro tinham uma mesma semelhança; sua aparência e sua obra era como se uma roda estivesse no meio de [outra] roda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 17, 'Quando andavam, moviam-se sobre seus quatro lados; não viravam quando se moviam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 18, 'E seus aros eram altos e espantosos; e seus aros estavam cheios de olhos ao redor das quatro [rodas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 19, 'E quando os animais andavam, as rodas andavam junto a eles: e quando os animais se levantavam da terra, levantavam-se [também] as rodas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 20, 'Para onde o espírito queria ir, iam, para onde era o espírito ia; e as rodas [também] se levantavam com eles, pois o espírito dos animais estava nas rodas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 21, 'Quando eles andavam, elas andavam; e quando eles paravam, elas paravam; e quando se levantavam da terra, as rodas se levantavam com eles; pois o espírito dos animais estava nas rodas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 22, 'E sobre as cabeças dos animais havia algo semelhante a um firmamento, da cor de um cristal espantoso, estendido acima sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 23, 'E debaixo do firmamento estavam suas asas deles estendidas uma à outra; a cada um tinha duas, e outras duas com que cobriam seus corpos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 24, 'E ouvi o ruído de suas asas quando se moviam, como o som de muitas águas, como a voz do Onipotente, o ruído de uma multidão, como o som de um exército. Quando paravam, abaixavam suas asas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 25, 'E quando se paravam e abaixavam suas asas, ouvia-se uma voz de cima do firmamento que estava sobre suas cabeças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 26, 'E acima do firmamento que estava sobre suas cabeças, havia a figura de um trono, que parecia com a pedra de safira; e sobre a figura do trono havia uma semelhança que parecia com um homem sentado acima dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 27, 'E vi o que parecia com o bronze polido, com a aparência de fogo ao seu redor do lado de dentro, da aparência de sua cintura para cima; e de sua cintura para baixo, vi que parecia como fogo, e havia um resplendor ao redor dele;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 1, 28, 'Tal como a aparência do arco celeste, que surge nas nuvens em dia de chuva, assim era o aparência do resplendor ao redor. Esta foi a visão da semelhança da glória do SENHOR. E quando eu a vi, caí sobre meu rosto, e ouvi voz de um que falava.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 1, 'E Disse-me: Filho do homem, fica de pé, e falarei contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 2, 'Então entrou em mim o Espírito enquanto falava comigo, e fez-me ficar de pé, e ouvi àquele que estava falando comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 3, 'E disse-me: Filho do homem, eu te envio aos filhos de Israel, às nações rebeldes que se rebelaram contra mim; eles e seus pais têm transgredido contra mim até este dia de hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 4, 'Pois são filhos duros de rosto e obstinados de coração; eu te envio a eles; e tu lhes dirás: Assim diz o Senhor DEUS.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 5, 'E eles, quer ouçam, quer deixem [de ouvir] ,(pois são uma casa rebelde) mesmo assim saberão que houve profeta entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 6, 'E tu, filho do homem, não os temas, nem temas suas palavras, ainda que estejas entre sarças e espinheiros, e tu habites com escorpiões; não temas suas palavras, nem te espantes pela presença deles, ainda que sejam uma casa rebelde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 26, 'Ezequiel', 'Ez', 2, 7, 'Tu falarás minhas palavras, quer ouçam, quer deixem [de ouvir] ; pois são rebeldes.')
